@dataclass
class Objet2A6Item:
    longueur_cm: float | None = None
    largeur_cm: float | None = None
    hauteur_cm: float | None = None
    type_calage: str | None = None
    plateau_interieur: str | None = None
    base: str | None = None
    nombre_calages: float | None = None
    type_mousse_calage: str | None = None

@dataclass
class Objet2A6Inputs:
    type_contreplaque: str | None = None
    barres: str | None = None
    garnissage: str | None = None
    type_isolant: str | None = None
    fermeture: str | None = None
    peinture: str | None = None
    poignees: str | None = None
    skis: str | None = None
    cuvette_au_dessus: str | None = None
    responsable_dossier: str | None = None
    client: str | None = None
    delai: str | None = None
    objets: list[Objet2A6Item] = field(default_factory=list)

def _num(x, default=0):
    if x in (None, ''): return default
    try: return float(str(x).replace(',', '.'))
    except Exception: return default

def _eq(a,b): return str(a or '').strip().lower() == str(b or '').strip().lower() if isinstance(a,str) or isinstance(b,str) else a==b

def _if(cond, a, b): return a if bool(cond) else b

def _sum(*args):
    total=0
    for arg in args:
        if isinstance(arg, list):
            total += _sum(*arg)
        elif isinstance(arg,(int,float)):
            total += arg
    return total

def _max(*args):
    vals=[]
    for arg in args:
        vals += arg if isinstance(arg,list) else [arg]
    nums=[v for v in vals if isinstance(v,(int,float))]
    return max(nums) if nums else 0

def _roundup(x, n=0):
    try:
        x=float(x); n=int(n); m=10**n
        return math.ceil(x*m)/m
    except Exception: return 0

def _concat(*args): return ''.join(str(a) for a in args)

class Engine:
    def __init__(self):
        self.cells={'Objet 2 à 6': {k: dict(v) for k,v in OBJ_CELLS.items()}, 'Prix Matiere': {k: dict(v) for k,v in PRIX_CELLS.items()}}
        self.cache={}
    def set(self, addr, value, sheet='Objet 2 à 6'):
        self.cells.setdefault(sheet, {})[addr]={'v': value}
        self.cache.pop((sheet,addr), None)
    def cell(self, addr, sheet='Objet 2 à 6'):
        addr=addr.replace('$','')
        key=(sheet,addr)
        if key in self.cache: return self.cache[key]
        item=self.cells.get(sheet,{}).get(addr,{})
        if 'f' in item:
            val=self.eval_formula(item['f'], sheet)
        else:
            val=item.get('v', 0)
        if val is None or val=='': val=0
        self.cache[key]=val
        return val
    def range_vals(self, ref, sheet='Objet 2 à 6'):
        ref=ref.replace('$','')
        if '!' in ref:
            sh,ref=ref.split('!',1); sheet=sh.strip("'").replace('[1]','')
        a,b=ref.split(':')
        r1,c1=addr_to_rc(a); r2,c2=addr_to_rc(b)
        out=[]
        for r in range(min(r1,r2), max(r1,r2)+1):
            row=[]
            for c in range(min(c1,c2), max(c1,c2)+1): row.append(self.cell(rc_to_addr(r,c), sheet))
            out.append(row)
        return out
    def vlookup(self, key, table, col, approx=True):
        if isinstance(table,str): table=self.range_vals(table)
        col=int(col)-1
        last=None
        for row in table:
            if not row: continue
            if _eq(row[0], key):
                return row[col] if col < len(row) else 0
            last=row
        return 0
    def name_ref(self, name):
        target=DEFINED.get(name) or DEFINED.get(name.replace('_G_', '_Gé')) or DEFINED.get(name.replace('Frais_Generaux','Frais_Généraux'))
        if not target: return 0
        target=target.replace('[1]','')
        if '!' in target:
            sh,ref=target.split('!',1); sh=sh.strip("'")
        else: sh,ref='Objet 2 à 6',target
        ref=ref.replace('$','')
        if ':' in ref: return self.range_vals(ref, sh)
        return self.cell(ref, sh)
    def eval_formula(self, formula, sheet):
        expr=formula.strip()
        expr=re.sub(r"'\[1\]([^']+)'!", r"'\1'!", expr)
        placeholders=[]
        def ph(txt):
            placeholders.append(txt); return f'__PH{len(placeholders)-1}__'
        # Protect string literals first.
        expr=re.sub(r'"[^"\\]*(?:\\.[^"\\]*)*"', lambda m: ph(m.group(0)), expr)
        # Excel text comparisons are case-insensitive. Translate simple equality tests to _eq(a,b).
        comp_token = r"(?:'[^']+'!\$?[A-Z]+\$?\d+|\$?[A-Z]+\$?\d+|[A-Za-z_À-ÿ][A-Za-z0-9_À-ÿ]*|__PH\d+|\d+(?:\.\d+)?)"
        expr=re.sub(r"(?<![<>=!A-Za-z0-9_])("+comp_token+r")\s*=\s*("+comp_token+r")", r"_eq(\1,\2)", expr)
        # Protect/translate sheet-qualified refs before local refs.
        expr=re.sub(r"'([^']+)'!\$?([A-Z]+\$?\d+:\$?[A-Z]+\$?\d+)", lambda m: ph(f"self.range_vals('{m.group(2)}','{m.group(1).replace('[1]','')}')"), expr)
        expr=re.sub(r"'([^']+)'!\$?([A-Z]+\$?\d+)", lambda m: ph(f"self.cell('{m.group(2)}','{m.group(1).replace('[1]','')}')"), expr)
        # Sheet-qualified named ranges.
        expr=re.sub(r"'([^']+)'!([A-Za-z_À-ÿ][A-Za-z0-9_À-ÿ]*)", lambda m: ph(f"self.name_ref('{m.group(2)}')"), expr)
        # Local refs/ranges.
        expr=re.sub(r"\$?([A-Z]+\$?\d+:\$?[A-Z]+\$?\d+)", lambda m: f"self.range_vals('{m.group(1)}','{sheet}')", expr)
        expr=re.sub(r"(?<![A-Za-z0-9_'])\$?([A-Z]+\$?\d+)(?![A-Za-z0-9_'])", lambda m: f"self.cell('{m.group(1)}','{sheet}')", expr)
        # Functions.
        repl={'IF':'_if','VLOOKUP':'self.vlookup','MAX':'_max','SUM':'_sum','ROUNDUP':'_roundup','CONCATENATE':'_concat'}
        for k,v in repl.items(): expr=re.sub(r'\b'+k+r'\s*\(', v+'(', expr)
        # Named ranges.
        for name in sorted(DEFINED, key=len, reverse=True):
            safe=name.replace('é','e').replace('è','e')
            expr=re.sub(r"(?<![A-Za-z0-9_])"+re.escape(name)+r"(?![A-Za-z0-9_])", f"self.name_ref('{name}')", expr)
            if safe!=name:
                expr=re.sub(r"(?<![A-Za-z0-9_])"+re.escape(safe)+r"(?![A-Za-z0-9_])", f"self.name_ref('{name}')", expr)
        expr=expr.replace('<>','!=')
        expr=re.sub(r'\bTRUE\b', 'True', expr)
        expr=re.sub(r'\bFALSE\b', 'False', expr)
        expr=re.sub(r'(?<![<>=!])=(?!=)', '==', expr)
        for i,txt in enumerate(placeholders): expr=expr.replace(f'__PH{i}__', txt)
        try:
            return eval(expr, {'__builtins__': {}}, {'self':self,'_if':_if,'_eq':_eq,'_sum':_sum,'_max':_max,'_roundup':_roundup,'_concat':_concat})
        except Exception:
            return 0

def col_to_num(col):
    n=0
    for c in col.replace('$',''):
        n=n*26+ord(c)-64
    return n

def addr_to_rc(addr):
    m=re.match(r'\$?([A-Z]+)\$?(\d+)$', addr.replace('$',''))
    return int(m.group(2)), col_to_num(m.group(1))

def rc_to_addr(r,c):
    s=''
    while c:
        c,rem=divmod(c-1,26); s=chr(65+rem)+s
    return f'{s}{r}'

def _choices_from_col(start, end):
    e=Engine(); vals=[]
    r1,c1=addr_to_rc(start); r2,c2=addr_to_rc(end)
    for r in range(r1,r2+1):
        v=e.cell(rc_to_addr(r,c1))
        if v not in (0,'',None) and v not in vals: vals.append(v)
    return vals

def options_objet2a6():
    e=Engine()
    def choices(range_ref):
        vals=[]
        for row in e.range_vals(range_ref):
            v=row[0] if row else 0
            if v not in (0,'',None) and v not in vals: vals.append(v)
        return vals
    return {
        'type_contreplaque': choices('A268:A269'),
        'barres': choices('A271:A272'),
        'garnissage': ['Oui','Non'],
        'type_isolant': choices('A249:A255'),
        'fermeture': ['Vis bois','Boulons et platines'],
        'peinture': ['Non','Oui'],
        'poignees': ['Bois','Non','Métal x 2 sur bouts'],
        'skis': ['Skis','10 dessous en skis','10 dessous en semelles'],
        'cuvette_au_dessus': ['Non','Oui'],
        'type_calage': choices('A234:A244'),
        'plateau_interieur': choices('A274:A280'),
        'base': choices('A283:A293'),
    }

def calculer_objet2a6(inputs: Objet2A6Inputs):
    e=Engine()
    e.set('C13', inputs.type_contreplaque or 'Peuplier 15 mm')
    e.set('C15', inputs.barres or 'Pin raboté 4 faces')
    e.set('F15', inputs.garnissage or 'Oui')
    e.set('C17', inputs.type_isolant or 'Aucun')
    e.set('C19', inputs.fermeture or 'Vis bois')
    e.set('F18', inputs.peinture or 'Non')
    e.set('C21', inputs.poignees or 'Bois')
    e.set('F21', inputs.skis or 'Skis')
    e.set('C23', inputs.cuvette_au_dessus or 'Non')
    e.set('F9', inputs.responsable_dossier or 'greg')
    e.set('F10', inputs.client or 'ESI')
    slots=[('C26','D26','E26','C27','C28','C29','E27'),('C33','D33','E33','C34','C35','C36','E34'),('C40','D40','E40','C41','C42','C43','E41'),('H26','I26','J26','H27','H28','H29','J27'),('H33','I33','J33','H34','H35','H36','J34'),('H40','I40','J40','H41','H42','H43','J41')]
    for idx,slot in enumerate(slots):
        item=inputs.objets[idx] if idx < len(inputs.objets) else Objet2A6Item()
        l,w,h,cal,plat,base,nb=slot
        e.set(l, _num(item.longueur_cm,0)); e.set(w, _num(item.largeur_cm,0)); e.set(h, _num(item.hauteur_cm,0))
        e.set(cal, item.type_calage or 'Aucun'); e.set(plat, item.plateau_interieur or 'Aucun'); e.set(base, item.base or 'Aucun')
        if item.nombre_calages not in (None,''): e.set(nb, _num(item.nombre_calages,0))
    return {
        'dimensions_interieures_longueur': e.cell('C56'),
        'dimensions_interieures_epaisseur': e.cell('D56'),
        'dimensions_interieures_hauteur': e.cell('E56'),
        'dimensions_exterieures_longueur': e.cell('C58'),
        'dimensions_exterieures_epaisseur': e.cell('D58'),
        'dimensions_exterieures_hauteur': e.cell('E58'),
        'poids_caisse': e.cell('C60'),
        'minutes_production': e.cell('C61'),
        'prix_vente': e.cell('C226'),
        'bilan_carbone': e.cell('C60'),
    }
